export const expandedCategories = expandedPackSeeds.map(
  ({ id, name, description, icon, colorTheme, recommendedGradeBand }) => ({
    id,
    name,
    slug: id,
    description,
    icon,
    colorTheme,
    recommendedGradeBand,
  }),
) satisfies Category[];

export const expandedPuzzles = expandedPackSeeds.flatMap((pack) =>
  pack.cards.map(
    ([answer, emojis, hint, details, funFact, difficulty = "easy", explanation, tags, stableId]) => ({
      id: stableId ? `${pack.id}-${stableId}` : `${pack.id}-${slugify(answer)}`,
      answer,
      emojis,
      categoryId: pack.id,
      difficulty,
      hint,
      details,
      explanation,
      funFact,
      tags: tags ? [...new Set(tags)] : [...new Set([...pack.tags, pack.id])],
    }),
  ),
) satisfies Puzzle[];

function slugify(value: string) {
  return value
    .toLowerCase()
    .replace(/&/g, "and")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
}
